/// Expansion of entry `index`.
fn value(index: usize) -> &'static str {
    let start = if index == 0 { 0 } else { VALUE_ENDS[index - 1] as usize };
    &VALUES[start..VALUE_ENDS[index] as usize]
}

pub(crate) fn get_entity(bytes: &[u8]) -> Option<&'static str> {
    let (mut low, mut high) = (0, COUNT);
    while low < high {
        let mid = (low + high) / 2;
        match name(mid).cmp(bytes) {
            core::cmp::Ordering::Less => low = mid + 1,
            core::cmp::Ordering::Greater => high = mid,
            core::cmp::Ordering::Equal => return Some(value(mid)),
        }
    }
    None
}

#[cfg(test)]
mod tests {
    // Inline module in src/entities.rs: paths resolve from src/entities/tests/.
    #[path = "../../entities_original.rs"]
    #[allow(dead_code)]
    mod original;

    /// Every upstream entity resolves identically, and near-miss names do not.
    #[test]
    fn packed_table_matches_upstream() {
        let mut checked = 0;
        for name in original::names() {
            assert_eq!(super::get_entity(name), original::get_entity(name), "entity {:?}", core::str::from_utf8(name));
            let mut longer = name.to_vec();
            longer.push(b'x');
            assert_eq!(super::get_entity(&longer), original::get_entity(&longer));
            assert_eq!(super::get_entity(&name[..name.len() - 1]), original::get_entity(&name[..name.len() - 1]));
            checked += 1;
        }
        assert_eq!(checked, super::COUNT);
        assert_eq!(super::get_entity(b""), None);
        assert_eq!(super::get_entity(b"notanentity"), None);
    }
}